# Let me check more pages to find transactions from 2023-05-17
for page in range(1, 10):
    transactions_result = apis.venmo.show_transactions(access_token=token, page_index=page)
    print(f"\n--- Page {page} ---")
    for txn in transactions_result:
        created_date = txn['created_at'][:10]  # Get just the date part
        if created_date == '2023-05-17':
            print(f"FOUND: Date: {txn['created_at']}, Amount: {txn['amount']}, Description: {txn['description']}")
            print(f"  Sender: {txn['sender']['name']}, Receiver: {txn['receiver']['name']}")
        elif created_date >= '2023-05-16':
            print(f"Date: {txn['created_at']}, Amount: {txn['amount']}, Description: {txn['description']}")

