action.code:
# Now I need to get details of all songs to check their genres and play counts
# Let me start by collecting all song IDs from liked songs, albums, and playlists

song_ids = set()

# From liked songs
for song in liked_songs:
    song_ids.add(song['song_id'])

# From liked albums - get song IDs from each album
for album in liked_albums:
    for song_id in album['song_ids']:
        song_ids.add(song_id)

# From playlists - get song IDs from each playlist
for playlist in playlists:
    for song_id in playlist['song_ids']:
        song_ids.add(song_id)

print(f"Total unique song IDs collected: {len(song_ids)}")
print(f"Song IDs: {sorted(song_ids)}")

# Now I need to get private information about songs to check play counts
# Let me get the private info for each song to get accurate play counts
songs_with_private = []

for song_id in sorted(song_ids):
    try:
        private_info = apis.spotify.show_song_privates(access_token=token, song_id=song_id)
        songs_with_private.append(private_info)
    except Exception as e:
        print(f"Error getting private info for song {song_id}: {e}")

print(f"Retrieved private info for {len(songs_with_private)} songs")
if songs_with_private:
    print("First private info example:", songs_with_private[0])

