action.code:
# Get all saved albums and extract their tracks
page_index = 0
while True:
    saved_albums = apis.spotify.get_saved_albums(access_token=token, limit=50, page_index=page_index)
    if not saved_albums.get('items'):
        break
    for item in saved_albums['items']:
        album_id = item['album']['id']
        # Get tracks from this album
        album_page = 0
        while True:
            album_tracks = apis.spotify.get_album_tracks(access_token=token, album_id=album_id, limit=50, page_index=album_page)
            if not album_tracks.get('items'):
                break
            for track in album_tracks['items']:
                unique_songs.add(track['id'])
            album_page += 1
    page_index += 1

print(f"Total unique songs after adding albums: {len(unique_songs)}")

