from datetime import datetime

sent_transactions_may = []
for tx in transactions:
    if tx['sender']['email'] == 'joseharr@gmail.com':
        created_date = datetime.fromisoformat(tx['created_at'])
        if created_date.year == 2023 and created_date.month == 5:
            sent_transactions_may.append(tx)

print(f"Sent transactions in May 2023: {sent_transactions_may}")
print(f"Count: {len(sent_transactions_may)}")

# Filter for transactions sent by Jose Harrison in May 2023
from datetime import datetime

may_sent_transactions = []
for trans in transactions:
    if trans['sender']['email'] == 'joseharr@gmail.com':
        created_date = datetime.fromisoformat(trans['created_at'])
        if created_date.year == 2023 and created_date.month == 5:
            may_sent_transactions.append(trans)

print(f"Transactions sent in May 2023: {may_sent_transactions}")
print(f"Total likes: {sum(t['like_count'] for t in may_sent_transactions)}")

# Let me check all transactions to see what months are available
